import 'package:flutter/material.dart';
import 'package:supabase_flutter/supabase_flutter.dart';
import 'backend.dart';import 'profile.dart';import 'compose.dart';
class SupabaseReady{static Future<List<Map<String,dynamic>>> feed()async{try{Supabase.instance.client;return Backend.feed();}catch(_){return [{'id':1,'body':'近くの人の日常が、ここに流れます。','profiles':{'username':'mii','instagram_username':'mii'},'interests':{'name':'カフェ'}},{'id':2,'body':'仕事終わり。ちょっとだけ飲む。','profiles':{'username':'kei','instagram_username':'kei'},'interests':{'name':'酒'}}];}}}
class FeedScreen extends StatefulWidget{const FeedScreen({super.key});@override State<FeedScreen> createState()=>_FeedScreenState();}
class _FeedScreenState extends State<FeedScreen>{int tab=0,refresh=0;@override Widget build(BuildContext context){final pages=[Feed(key:ValueKey(refresh)),const Center(child:Text('通知')),const MyProfile()];return Scaffold(appBar:AppBar(title:const Text('neap',style:TextStyle(fontWeight:FontWeight.w800))),body:pages[tab],floatingActionButton:tab==0?FloatingActionButton(onPressed:()async{final ok=await Navigator.push<bool>(context,MaterialPageRoute(builder:(_)=>const ComposeScreen()));if(ok==true)setState(()=>refresh++);},child:const Icon(Icons.add)):null,bottomNavigationBar:NavigationBar(selectedIndex:tab,onDestinationSelected:(i)=>setState(()=>tab=i),destinations:const[NavigationDestination(icon:Icon(Icons.home_outlined),label:'Home'),NavigationDestination(icon:Icon(Icons.notifications_none),label:'通知'),NavigationDestination(icon:Icon(Icons.person_outline),label:'Me')]));}}
class Feed extends StatelessWidget{const Feed({super.key});@override Widget build(BuildContext context)=>FutureBuilder<List<Map<String,dynamic>>>(future:SupabaseReady.feed(),builder:(context,s){if(s.hasError)return Center(child:Text('読み込みエラー\n'+s.error.toString()));if(!s.hasData)return const Center(child:CircularProgressIndicator());final posts=s.data!;if(posts.isEmpty)return const Center(child:Text('まだ投稿がありません'));return ListView.separated(itemCount:posts.length,separatorBuilder:(_,__)=>const Divider(height:1),itemBuilder:(_,i){final p=posts[i];final profile=(p['profiles'] as Map?)??{};final interest=(p['interests'] as Map?)??{};final name=(profile['username']??'user').toString();final insta=profile['instagram_username']?.toString();return Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Row(children:[const CircleAvatar(child:Icon(Icons.person)),const SizedBox(width:10),Text(name,style:const TextStyle(fontWeight:FontWeight.w700)),const Spacer(),if(p['distance_m']!=null)const Text('近く')]),if(p['image_url']!=null)...[const SizedBox(height:14),ClipRRect(borderRadius:BorderRadius.circular(14),child:Image.network(p['image_url'],width:double.infinity,fit:BoxFit.cover))],if((p['body']??'').toString().isNotEmpty)...[const SizedBox(height:12),Text(p['body'],style:const TextStyle(fontSize:16))],if(interest['name']!=null)Text('#'+interest['name'].toString()),Row(children:[IconButton(onPressed:(){},icon:const Icon(Icons.favorite_border)),IconButton(onPressed:(){},icon:const Icon(Icons.chat_bubble_outline)),const Spacer(),if(insta!=null&&insta.isNotEmpty)TextButton(onPressed:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>ProfileScreen(name:name,instagram:insta))),child:const Text('Instagram'))])])) ;});});}
